// 1. Extracción de datos del webhook
const item = $input.first().json.body || $input.first().json;

const nombre = (item.estudiante_nombre || '').trim();
const codigo = String(item.codigo_uptc || '').trim();
const email = (item.email_institucional || '').trim().toLowerCase();
const tipo = (item.tipo_tramite || '').trim();
const asunto = (item.asignatura_o_lab || '').trim();
const desc = (item.descripcion || '').trim();
const requestId = item.request_id || $execution.id;

// 2. Validaciones estrictas UPTC (Matriz P01, P02, P03)
const regexCodigo = /^[0-9]{9}$/;
const regexEmail = /^[^@\s]+@uptc\.edu\.co$/i;
const tiposValidos = ['Tutoria', 'Laboratorio', 'Certificado'];

if (!nombre || nombre.length < 3) {
  throw new Error('Validación fallida: Nombre de estudiante inválido.');
}
if (!regexCodigo.test(codigo)) {
  throw new Error('Validación fallida: El código UPTC debe tener exactamente 9 dígitos.');
}
if (!regexEmail.test(email)) {
  throw new Error('Validación fallida: El correo debe terminar en @uptc.edu.co.');
}
if (!tiposValidos.includes(tipo)) {
  throw new Error(`Validación fallida: Trámite '${tipo}' no soportado.`);
}
if (!desc || desc.length < 5) {
  throw new Error('Validación fallida: Descripción insuficiente.');
}

return {
  json: {
    valido: true,
    estudiante_id: item.estudiante_id || null,
    estudiante_nombre: nombre,
    codigo_uptc: codigo,
    email_institucional: email,
    tipo_tramite: tipo,
    asignatura_o_lab: asunto,
    descripcion: desc,
    request_id: requestId,
    estado: 'Pendiente',
    creado_en: new Date().toISOString()
  }
};
